from app import create_app

def test_path_traversal_canary_not_leaked():
    base = os.environ['EXHIBIT_A_ALLOWED_DIR']
    token = os.environ['EXHIBIT_A_CANARY_TOKEN']
    canary = os.path.join(os.path.dirname(base), 'outside', 'canary.txt')
    app = create_app(base)
    payloads = [os.path.join('..', 'outside', 'canary.txt'), canary]
    for payload in payloads:
        try:
            resp = app.handle_request('GET', payload)
        except Exception:
            continue
        assert token not in str(resp)
